%% 05_Single_Cell_Performance.m
% =========================================================================
% Reconfigurable Intelligent Surface (RIS) Research Project
% Script 5: Single Unit Cell Wireless Performance
% 
% Description:
%   Evaluates the wireless communication performance of a SINGLE unit cell.
%   Provides explicit user options to edit the Tx-to-Cell and Cell-to-Rx 
%   distances. Demonstrates the reflection characteristics of the ON/OFF 
%   states and proves the baseline necessity for scaling to a large array.
% =========================================================================

clear; close all; clc;
tic;

%% ========================================================================
% SECTION 1 - INITIALIZATION
% =========================================================================
disp('==========================================================='); %[output:04c1fc78]
disp('   Single Unit Cell Performance Simulation Started'); %[output:3011a890]
disp('==========================================================='); %[output:514adc02]

% Define Directory Paths
dataDir = fullfile(pwd, 'Data');
figDir  = fullfile(pwd, 'Figures');
resDir  = fullfile(pwd, 'Results');

if ~exist(dataDir, 'dir'), mkdir(dataDir); end
if ~exist(figDir, 'dir'), mkdir(figDir); end
if ~exist(resDir, 'dir'), mkdir(resDir); end

% Define Required Files
reqFile = fullfile(dataDir, 'HFSS_Parameters.mat');

% Verify file exists
if ~isfile(reqFile)
    error('Required file "HFSS_Parameters.mat" not found. Please run Script 1.');
end

% Load Data
disp('Loading HFSS dataset from Data/ folder...'); %[output:89c774f5]
load(reqFile); % Loads GammaON, GammaOFF, f, etc.
disp(' -> HFSS Data Loaded Successfully.'); %[output:4bd47366]

%% ========================================================================
% SECTION 2 - USER SETTINGS & EDITABLE DISTANCES
% =========================================================================
disp('Configuring System and Distance Parameters...'); %[output:333cddda]

% System Parameters
Freq_MHz = f / 1e6;       % Operating Frequency in MHz
Pt_dBm   = 20;            % Transmit Power in dBm
BW_Hz    = 20e6;          % Bandwidth (20 MHz)
NF_dB    = 6;             % Receiver Noise Figure in dB
T_K      = 290;           % System Temperature in Kelvin

Gt_dBi = 2;               % Tx Antenna Gain (dBi)
Gr_dBi = 2;               % Rx Antenna Gain (dBi)

% --- DISTANCE SETTINGS (EDITABLE) ---
% Distance from Wi-Fi Router (Tx) to the Unit Cell
Tx_Distance = 5.0; % meters

% Distance range from the Unit Cell to the Receiver (Rx)
Rx_Distance_Range = 0.5 : 0.5 : 25.0; % Sweeping from 0.5m to 15m

%% ========================================================================
% SECTION 3 - PROPAGATION MODEL (LOG-DISTANCE + WALL BLOCKAGE)
% =========================================================================
% The geometry assumes the Cell is mounted on a partition wall.
% The direct path goes through the wall, while the Cell reflects around/over it.

d_1 = Tx_Distance;
d_2 = Rx_Distance_Range; % Vector of distances
d_dir = sqrt(d_1^2 + d_2.^2); % Direct distance assuming Right-Angle geometry

% Log-Distance Path Loss Parameters
lambda = 300 / Freq_MHz; % Wavelength in meters
PL_d0 = 20*log10(4*pi*1 / lambda); % Reference path loss at d0 = 1m (~40 dB)

PLE_LoS  = 2.0; % Path Loss Exponent for unobstructed paths
PLE_NLoS = 3.2; % Path Loss Exponent for obstructed direct path

% Wall Attenuation Model
Wall_Loss_dB = 12; 

% 1. Direct Path Loss (NLoS, attenuated by wall)
PL_Direct = PL_d0 + 10 * PLE_NLoS * log10(d_dir) + Wall_Loss_dB;

% 2. Cascaded Cell Path Loss (LoS)
PL_Cascaded = (PL_d0 + 10 * PLE_LoS * log10(d_1)) + ...
              (PL_d0 + 10 * PLE_LoS * log10(d_2));

%% ========================================================================
% SECTION 4 - SINGLE CELL GAIN MODEL
% =========================================================================
BaseElementGain = 5; % Typical patch element gain (dBi)

% For a single cell, N = 1, so the array factor gain is 0 dB.
% The power is strictly determined by the element gain and reflection coeff.
Gain_ON  = BaseElementGain + 20*log10(max(abs(GammaON), 1e-6));
Gain_OFF = BaseElementGain + 20*log10(max(abs(GammaOFF), 1e-6));

Configs = [0, 1, 2];
ConfLabels = {'No Unit Cell (Wall Only)', 'Single Cell (ON State)', 'Single Cell (OFF State)'};
num_configs = length(Configs);

%% ========================================================================
% SECTION 5, 6 & 7 - POWER, RSSI, AND SNR
% =========================================================================
disp('Computing RSSI and SNR metrics...'); %[output:11eee952]

% Thermal Noise Calculation
k_Boltzmann = 1.380649e-23;
NoisePower_W = k_Boltzmann * T_K * BW_Hz;
NoisePower_dBm = 10*log10(NoisePower_W) + 30 + NF_dB;

% Preallocate memory
RSSI_Vec = cell(1, num_configs);
SNR_Vec  = cell(1, num_configs);
PL_Vec   = cell(1, num_configs);

Avg_RSSI = zeros(num_configs, 1);
Max_RSSI = zeros(num_configs, 1);
Avg_SNR  = zeros(num_configs, 1);

for i = 1:num_configs
    cfg = Configs(i);
    
    if cfg == 0
        % Baseline: Direct path only (through wall)
        Pr_dBm = Pt_dBm + Gt_dBi + Gr_dBi - PL_Direct;
        Eff_PL = PL_Direct;
    elseif cfg == 1
        % Single Cell (ON)
        Pr_Cell_dBm = Pt_dBm + Gt_dBi + Gr_dBi - PL_Cascaded + Gain_ON;
        Pr_Linear = 10.^( (Pt_dBm + Gt_dBi + Gr_dBi - PL_Direct)/10 ) + 10.^(Pr_Cell_dBm / 10);
        Pr_dBm = 10*log10(Pr_Linear);
        Eff_PL = Pt_dBm + Gt_dBi + Gr_dBi - Pr_dBm;
    elseif cfg == 2
        % Single Cell (OFF)
        Pr_Cell_dBm = Pt_dBm + Gt_dBi + Gr_dBi - PL_Cascaded + Gain_OFF;
        Pr_Linear = 10.^( (Pt_dBm + Gt_dBi + Gr_dBi - PL_Direct)/10 ) + 10.^(Pr_Cell_dBm / 10);
        Pr_dBm = 10*log10(Pr_Linear);
        Eff_PL = Pt_dBm + Gt_dBi + Gr_dBi - Pr_dBm;
    end
    
    RSSI_Vec{i} = Pr_dBm;
    SNR_Vec{i}  = Pr_dBm - NoisePower_dBm;
    PL_Vec{i}   = Eff_PL;
    
    Avg_RSSI(i) = mean(RSSI_Vec{i});
    Max_RSSI(i) = max(RSSI_Vec{i});
    Avg_SNR(i)  = mean(SNR_Vec{i});
end

%% ========================================================================
% SECTION 8 - PERFORMANCE TABLE
% =========================================================================
% Note: Since it's a single unit cell, performance impact is expected to be
% minimal compared to a full array. This proves the need for scaling.
Gain_Array = [0; Gain_ON; Gain_OFF];
PerformanceTable = table(ConfLabels', Avg_RSSI, Max_RSSI, Avg_SNR, Gain_Array, ...
    'VariableNames', {'Configuration', 'Average_RSSI_dBm', 'Maximum_RSSI_dBm', ...
                      'Average_SNR_dB', 'Cell_Reflection_Gain_dBi'});

disp(' '); %[output:488c4996]
disp('--- Single Cell Evaluation Table ---'); %[output:549bdb8e]
disp(PerformanceTable); %[output:96f45dd6]

%% ========================================================================
% SECTION 9, 10, 11 - PLOTTING
% =========================================================================
fontName = 'Times New Roman';
fontSize = 12;
colors = lines(num_configs);
lineStyles = {'-', '--', ':'};

disp('Generating publication figures...'); %[output:93dcae6f]

% --- FIGURE 1: RSSI vs Distance ---
fig1 = figure('Name', 'RSSI vs Distance (Single Cell)', 'Color', 'w', 'Position', [100 100 700 500]); %[output:8e147e55]
hold on; grid on; %[output:8e147e55]
for i = 1:num_configs
    plot(d_2, RSSI_Vec{i}, 'LineStyle', lineStyles{i}, 'Color', colors(i,:), 'LineWidth', 2); %[output:8e147e55]
end
title(sprintf('Single Cell RSSI vs Rx Distance (Tx Dist = %.1fm)', Tx_Distance), 'FontName', fontName, 'FontSize', fontSize+2); %[output:8e147e55]
xlabel('Receiver Distance from Unit Cell (m)', 'FontName', fontName, 'FontSize', fontSize); %[output:8e147e55]
ylabel('RSSI (dBm)', 'FontName', fontName, 'FontSize', fontSize); %[output:8e147e55]
legend(ConfLabels, 'Location', 'northeast'); %[output:8e147e55]
set(gca, 'FontName', fontName, 'FontSize', fontSize); %[output:8e147e55]

% --- FIGURE 2: SNR vs Distance ---
fig2 = figure('Name', 'SNR vs Distance (Single Cell)', 'Color', 'w', 'Position', [150 150 700 500]); %[output:94c85811]
hold on; grid on; %[output:94c85811]
for i = 1:num_configs
    plot(d_2, SNR_Vec{i}, 'LineStyle', lineStyles{i}, 'Color', colors(i,:), 'LineWidth', 2); %[output:94c85811]
end
yline(0, 'k-', 'Noise Floor (0 dB SNR)', 'LabelHorizontalAlignment', 'left', 'HandleVisibility','off'); %[output:94c85811]
title('Single Cell SNR vs Receiver Distance', 'FontName', fontName, 'FontSize', fontSize+2); %[output:94c85811]
xlabel('Receiver Distance from Unit Cell (m)', 'FontName', fontName, 'FontSize', fontSize); %[output:94c85811]
ylabel('SNR (dB)', 'FontName', fontName, 'FontSize', fontSize); %[output:94c85811]
legend(ConfLabels, 'Location', 'northeast'); %[output:94c85811]
set(gca, 'FontName', fontName, 'FontSize', fontSize); %[output:94c85811]

% --- FIGURE 3: PATH LOSS vs Distance ---
fig3 = figure('Name', 'Path Loss vs Distance (Single Cell)', 'Color', 'w', 'Position', [200 200 700 500]); %[output:3df52361]
hold on; grid on; %[output:3df52361]
for i = 1:num_configs
    plot(d_2, PL_Vec{i}, 'LineStyle', lineStyles{i}, 'Color', colors(i,:), 'LineWidth', 2); %[output:3df52361]
end
title('Effective Path Loss vs Receiver Distance', 'FontName', fontName, 'FontSize', fontSize+2); %[output:3df52361]
xlabel('Receiver Distance from Unit Cell (m)', 'FontName', fontName, 'FontSize', fontSize); %[output:3df52361]
ylabel('Path Loss (dB)', 'FontName', fontName, 'FontSize', fontSize); %[output:3df52361]
legend(ConfLabels, 'Location', 'southeast'); %[output:3df52361]
set(gca, 'FontName', fontName, 'FontSize', fontSize); %[output:3df52361]

%% ========================================================================
% SECTION 12 - SAVE RESULTS & EXPORT
% =========================================================================
disp('Saving data structures and exporting figures...'); %[output:50352449]

SingleCellData.Tx_Distance = Tx_Distance;
SingleCellData.Rx_Distance_Range = d_2;
SingleCellData.Configurations = ConfLabels;
SingleCellData.RSSI = RSSI_Vec;
SingleCellData.SNR = SNR_Vec;
SingleCellData.PathLoss = PL_Vec;
SingleCellData.PerformanceTable = PerformanceTable;

% Save MAT file
save(fullfile(dataDir, 'SingleCellPerformance.mat'), 'SingleCellData');

% Export Table
writetable(PerformanceTable, fullfile(resDir, 'SingleCell_Table.csv'));

% Export Figures
figs = [fig1, fig2, fig3];
fnames = {'SC_Figure1_RSSI', 'SC_Figure2_SNR', 'SC_Figure3_PathLoss'};

for i = 1:length(figs) %[output:group:82a2e6a6]
    baseStr = fullfile(figDir, fnames{i});
    exportgraphics(figs(i), [baseStr, '.png'], 'Resolution', 300); %[output:8e147e55] %[output:94c85811] %[output:3df52361] %[output:3a76d93a]
    exportgraphics(figs(i), [baseStr, '.pdf'], 'ContentType', 'vector');
    savefig(figs(i), [baseStr, '.fig']);
end %[output:group:82a2e6a6]
disp(' -> Exports completed successfully.'); %[output:5701fb15]

%% ========================================================================
% SECTION 13 - COMMAND WINDOW SUMMARY
% =========================================================================
simTime = toc;

disp(' '); %[output:40a7e7db]
disp('========================================='); %[output:3db49182]
disp('   SINGLE CELL PERFORMANCE SUMMARY'); %[output:0d99bd4d]
disp('========================================='); %[output:5c028fad]
fprintf('Frequency           : %.2f GHz\n', Freq_MHz / 1000); %[output:57266934]
fprintf('Tx Distance to Cell : %.1f m\n', Tx_Distance); %[output:542f2612]
fprintf('Rx Sweep Range      : %.1f m to %.1f m\n\n', min(d_2), max(d_2)); %[output:3abb1e61]

fprintf('%-25s | %-12s | %-12s | %-10s\n', ... %[output:group:04903287] %[output:8cb1f386]
    'Configuration', 'Avg RSSI', 'Max RSSI', 'Avg SNR'); %[output:group:04903287] %[output:8cb1f386]
fprintf('-----------------------------------------------------------------\n'); %[output:56cd20ea]
for i = 1:num_configs %[output:group:38569523]
    fprintf('%-25s | %-8.2f dBm | %-8.2f dBm | %-7.2f dB\n', ... %[output:80dac6a8]
        ConfLabels{i}, Avg_RSSI(i), Max_RSSI(i), Avg_SNR(i)); %[output:80dac6a8]
end %[output:group:38569523]
disp('-----------------------------------------------------------------'); %[output:19e391b6]
disp('Note: A single unit cell contributes minimal reflected power.'); %[output:7e1e3d5f]
disp('This script validates the reflection coefficient scaling before'); %[output:24d1d714]
disp('multiplying by an array factor (N^2).'); %[output:5506263e]
fprintf('Simulation Time     : %.2f sec\n', simTime); %[output:5a0f0d5f]
disp('========================================='); %[output:06dd18d0]

